if (!isset($qc_auth)) {
    $qc_auth = 0;

    if (isset($link, $PHP_AUTH_USER) && $PHP_AUTH_USER !== '') {
        $sidebar_user = mysqli_real_escape_string($link, $PHP_AUTH_USER);

        $stmt = "
            SELECT qc_enabled, qc_user_level, qc_pass, qc_finish, qc_commit
            FROM vicidial_users
            WHERE user = '$sidebar_user'
              AND user_level > 1
              AND active = 'Y'
              AND qc_enabled = '1'
            LIMIT 1
        ";

        if (!empty($DB)) {
            echo "<!-- $stmt -->\n";
        }

        $rslt = mysql_to_mysqli($stmt, $link);

        if ($rslt && mysqli_num_rows($rslt) > 0) {
            $row = mysqli_fetch_row($rslt);

            $qc_auth      = (int) $row[0];
            // $qcuser_level = $row[1];
            // $qcpass       = $row[2];
            // $qcfinish     = $row[3];
            // $qccommit     = $row[4];
        }
    }
}

