<script>
document.addEventListener("DOMContentLoaded", function () {
  /* ===============================
     SIDEBAR TOGGLE
  =============================== */
  const sidebarToggle = document.querySelector("#sidebarToggle");
  const mainRow = document.querySelector(".main_row");
  
  if (sidebarToggle && mainRow) {
    sidebarToggle.addEventListener("click", function (e) {
      e.preventDefault();
      mainRow.classList.toggle("sidebar-collapsed");
      // Save state in localStorage
      const isCollapsed = mainRow.classList.contains("sidebar-collapsed");
      localStorage.setItem("sidebar-collapsed", isCollapsed);
    });
    
    // Restore sidebar state on reload
    const savedState = localStorage.getItem("sidebar-collapsed");
    if (savedState === "true") {
      mainRow.classList.add("sidebar-collapsed");
    }
  }

  /* ===============================
     MAIN MENU WITH SUBMENU
  =============================== */
  document.querySelectorAll(".has-submenu > .menu-link").forEach(menuLink => {
  menuLink.addEventListener("click", function (e) {
    e.preventDefault();
    
    const parent = this.closest(".menu-item");
    const isAlreadyOpen = parent.classList.contains("open");

    // 1. Close all other open menus first (Accordion style)
    document.querySelectorAll(".menu-item.has-submenu.open").forEach(item => {
      item.classList.remove("open");
    });

    // 2. Toggle current menu: if it wasn't open, open it now
    if (!isAlreadyOpen) {
      parent.classList.add("open");
    }
    // If it was already open, the logic above already closed it
  });
});
  
  /* ===============================
     SIMPLE MENU (NO SUBMENU)
  =============================== */
  document.querySelectorAll(".menu-item:not(.has-submenu) > .menu-link")
    .forEach(link => {
      link.addEventListener("click", function () {
        // remove all submenu active
        document.querySelectorAll(".submenu a.active").forEach(a => {
          a.classList.remove("active");
        });
        // close all submenus
        document.querySelectorAll(".menu-item.has-submenu").forEach(item => {
          item.classList.remove("open");
        });
        // active current main menu
        document.querySelectorAll(".menu-link.active").forEach(a => {
          a.classList.remove("active");
        });
        this.classList.add("active");
        // save state
        localStorage.setItem("activeMainMenu", this.getAttribute("href"));
        localStorage.removeItem("activeSubmenu");
      });
    });
    
  /* ===============================
     SUBMENU ACTIVE
  =============================== */
  document.querySelectorAll(".submenu a").forEach(subLink => {
    subLink.addEventListener("click", function () {
      // remove all active
      document.querySelectorAll(".submenu a.active").forEach(a => {
        a.classList.remove("active");
      });
      document.querySelectorAll(".menu-link.active").forEach(a => {
        a.classList.remove("active");
      });
      // active current submenu
      this.classList.add("active");
      // open parent
      const parentMenu = this.closest(".menu-item");
      parentMenu.classList.add("open");
      // close others
      document.querySelectorAll(".menu-item.has-submenu").forEach(item => {
        if (item !== parentMenu) item.classList.remove("open");
      });
      // save state
      localStorage.setItem("activeSubmenu", this.getAttribute("href"));
      localStorage.removeItem("activeMainMenu");
    });
  });
  
  /* ===============================
     RESTORE STATE ON RELOAD
  =============================== */
  const savedSub = localStorage.getItem("activeSubmenu");
  const savedMain = localStorage.getItem("activeMainMenu");
  if (savedSub) {
    const link = document.querySelector('.submenu a[href="' + savedSub + '"]');
    if (link) {
      link.classList.add("active");
      link.closest(".menu-item").classList.add("open");
    }
  } 
  else if (savedMain) {
    const main = document.querySelector('.menu-link[href="' + savedMain + '"]');
    if (main) {
      main.classList.add("active");
    }
  }
});
</script>
